-- pup_homestead | install.sql
-- Builds everything this script needs on an empty database. Safe to run more than once.
--
-- Creates: homestead_plants, homestead_stats
-- Items: 84 rows
-- Requires: VORP core items. gang_seed and gang_drug must match pup-gangs/config/drugs.lua. playerfarms is read once if an older server still has it; not created here.

CREATE TABLE IF NOT EXISTS `homestead_plants` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `charid` int(11) NOT NULL,
  `crop` varchar(48) NOT NULL,  -- a Config.Crops key
  `x` double NOT NULL,
  `y` double NOT NULL,
  `z` double NOT NULL,
  `minutes_left` int(11) NOT NULL DEFAULT 0,
  `watered` tinyint(4) NOT NULL DEFAULT 0,
  `fertilised` tinyint(4) NOT NULL DEFAULT 0,
  `trimmed` tinyint(4) NOT NULL DEFAULT 0,
  `health` int(11) NOT NULL DEFAULT 100,
  `difficulty` int(11) NOT NULL DEFAULT 5,
  `restarts` int(11) NOT NULL DEFAULT 0,  -- restarts survived (Config.Plants.lifetimeRestarts)
  `ripe_minutes` int(11) NOT NULL DEFAULT 0,  -- minutes ripe and unpicked (Config.Plants.witherMinutes)
  `planted_at` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_char` (`charid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `homestead_stats` (
  `charid` int(11) NOT NULL,
  `crop` varchar(48) NOT NULL,
  `planted` int(11) NOT NULL DEFAULT 0,
  `harvested` int(11) NOT NULL DEFAULT 0,  -- plants of theirs harvested (by anyone)
  `gathered` int(11) NOT NULL DEFAULT 0,  -- produce they picked themselves
  PRIMARY KEY (`charid`,`crop`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

